    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

::deep .sidebar-header {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    text-transform: uppercase;
    color: #8e9297;
    border-bottom: 1px solid #202225;
}

::deep .channel-list {
    overflow-y: auto;
    flex: 1;
    padding: 8px 0;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #34373c;
}

::deep .channel-item.active {
    background: #393c43;
    color: #fff;
}

::deep .channel-name {
    font-weight: 600;
    flex: 1;
}

::deep .channel-description {
    width: 100%;
    font-size: 0.75rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
}

/* Main area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.thread-open {
    flex: 0 0 55%;
}

::deep .message-area {
    display: flex;
    flex-direction: column;
    flex: 1;
    background: #36393f;
    color: #dcddde;
}

::deep .channel-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .channel-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .channel-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

::deep .no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #8e9297;
}

/* Message list */
::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

::deep .loading-indicator {
    text-align: center;
    color: #8e9297;
    padding: 8px;
    font-size: 0.85rem;
}

/* Message bubble */
::deep .message-bubble {
    position: relative;
    padding: 8px 12px;
    border-radius: 4px;
    transition: background 0.1s;
}

::deep .message-bubble:hover {
    background: #32353b;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #72767d;
}

::deep .message-content {
    margin: 4px 0;
    line-height: 1.4;
    word-break: break-word;
}

::deep .message-reactions {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    margin-top: 4px;
}

::deep .reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dcddde;
    transition: background 0.1s;
}

::deep .reaction-badge:hover {
    background: #3c3f44;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    font-weight: 500;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

/* Message actions (hover overlay) */
::deep .message-actions {
    position: absolute;
    top: -4px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px;
}

::deep .action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 6px;
    font-size: 1rem;
    border-radius: 3px;
    transition: background 0.1s;
}

::deep .action-btn:hover {
    background: #3c3f44;
}

/* Emoji picker */
::deep .emoji-picker {
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 6px;
    padding: 6px;
    margin-top: 4px;
    width: fit-content;
}

::deep .emoji-option {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.2rem;
    padding: 4px;
    border-radius: 4px;
    transition: background 0.1s;
}

::deep .emoji-option:hover {
    background: #3c3f44;
}

/* Message input */
::deep .message-input-area {
    padding: 12px 20px;
    border-top: 1px solid #202225;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

::deep .message-textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    color: #dcddde;
    padding: 10px 14px;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

::deep .message-textarea::placeholder {
    color: #72767d;
}

::deep .send-btn {
    background: #5865f2;
