+}
+
+::deep .thread-link {
+    background: none;
+    border: none;
+    color: #00aff4;
+    font-size: 0.8rem;
+    cursor: pointer;
+    padding: 4px 0;
+    font-weight: 500;
+}
+
+::deep .thread-link:hover {
+    text-decoration: underline;
+}
+
+/* Message actions (hover overlay) */
+::deep .message-actions {
+    position: absolute;
+    top: -4px;
+    right: 8px;
+    display: flex;
+    gap: 2px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 2px;
+}
+
+::deep .action-btn {
+    background: none;
+    border: none;
+    cursor: pointer;
+    padding: 4px 6px;
+    font-size: 1rem;
+    border-radius: 3px;
+    transition: background 0.1s;
+}
+
+::deep .action-btn:hover {
+    background: #3c3f44;
+}
+
+/* Emoji picker */
+::deep .emoji-picker {
+    display: flex;
+    gap: 4px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 6px;
+    padding: 6px;
+    margin-top: 4px;
+    width: fit-content;
+}
+
+::deep .emoji-option {
+    background: none;
+    border: none;
+    cursor: pointer;
+    font-size: 1.2rem;
+    padding: 4px;
+    border-radius: 4px;
+    transition: background 0.1s;
+}
+
+::deep .emoji-option:hover {
+    background: #3c3f44;
+}
+
+/* Message input */
+::deep .message-input-area {
+    padding: 12px 20px;
+    border-top: 1px solid #202225;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+}
+
+::deep .message-textarea {
+    flex: 1;
+    background: #40444b;
+    border: none;
+    border-radius: 8px;
+    color: #dcddde;
+    padding: 10px 14px;
+    font-size: 0.9rem;
+    resize: none;
+    outline: none;
+    font-family: inherit;
+}
+
+::deep .message-textarea::placeholder {
+    color: #72767d;
+}
+
+::deep .send-btn {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 10px 18px;
+    font-weight: 600;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+::deep .send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+::deep .send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread panel */
+::deep .thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2f3136;
+    color: #dcddde;
+    border-left: 1px solid #202225;
+    display: flex;
+    flex-direction: column;
+}
+
+::deep .thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+::deep .close-btn {
+    background: none;
+    border: none;
+    color: #8e9297;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+    transition: background 0.1s;
+}
+
+::deep .close-btn:hover {
+    background: #3c3f44;
+    color: #fff;
+}
+
+::deep .thread-root-message {
+    padding: 12px 16px;
+    background: #36393f;
+    border-bottom: 1px solid #202225;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+::deep .thread-reply {
+    padding: 8px;
+    border-radius: 4px;
+}
+
+::deep .thread-reply:hover {
+    background: #34373c;
+}
+

